package android.system;import java.io.*;import java.nio.file.*;import java.nio.file.attribute.*;public class Os {public static boolean packetSocketReady;public static void chmod(String p,int mode)throws ErrnoException{try{Files.setPosixFilePermissions(Paths.get(p),PosixFilePermissions.fromString(mode==0700?"rwx------":"rw-------"));}catch(IOException e){throw new ErrnoException("chmod",5);}}public static StructStat stat(String p)throws ErrnoException{try{int uid=((Number)Files.getAttribute(Paths.get(p),"unix:uid")).intValue();int self=((Number)Files.getAttribute(Paths.get("/proc/self"),"unix:uid")).intValue();return new StructStat(uid==self?2000:uid);}catch(IOException e){throw new ErrnoException("stat",2);}}public static int read(FileDescriptor fd,byte[] b,int offset,int length)throws ErrnoException{return 0;}public static int write(FileDescriptor fd,byte[] b,int offset,int length)throws ErrnoException{return length;}public static int poll(StructPollfd[] p,int t){return packetSocketReady?1:0;}}